void handle_outbound_pinhole_timeout_retrieval(struct upnphttp *h, const char *action, const char *ns) {
    // Check if IPv6 forwarding is disabled
    if (!ipv6_forwarding_enabled()) {
        send_error_response(h, 400, "IPv6 forwarding is disabled");
        return;
    }

    // Parse request parameters
    char *internal_client_ip = parse_request_param(h->request, "InternalClient");
    char *internal_port = parse_request_param(h->request, "InternalPort");
    char *remote_host = parse_request_param(h->request, "RemoteHost");
    char *protocol = parse_request_param(h->request, "Protocol");

    // Check for missing parameters
    if (!internal_client_ip || !internal_port || !remote_host || !protocol) {
        send_error_response(h, 400, "Missing required parameters");
        return;
    }

    // Log request details
    log_request_details(h, action, ns, internal_client_ip, internal_port, remote_host, protocol);

    // Check outbound pinhole timeout
    int timeout = check_outbound_pinhole_timeout(internal_client_ip, internal_port, remote_host, protocol);

    if (timeout < 0) {
        send_error_response(h, 500, "Failed to retrieve timeout");
        return;
    } else if (timeout == 0) {
        send_soap_response(h, action, ns, "Invalid protocol or unsupported action");
    } else {
        char buffer[256];
        snprintf(buffer, sizeof(buffer), "%d", timeout);
        send_soap_response(h, action, ns, buffer);
    }
}

void handle_outbound_pinhole_timeout(struct upnphttp *h, const char *action, const char *ns) {
    const char *internalClient = upnp_http_GetRequestArg(h, "InternalClient");
    const char *internalPort = upnp_http_GetRequestArg(h, "InternalPort");
    const char *externalPort = upnp_http_GetRequestArg(h, "ExternalPort");
    const char *remoteHost = upnp_http_GetRequestArg(h, "RemoteHost");
    const char *protocol = upnp_http_GetRequestArg(h, "Protocol");

    if (!internalClient || !internalPort || !externalPort || !protocol) {
        upnp_http_SendErrorResponse(h, 400, "Invalid Args");
        return;
    }

    if (!is_ipv6_forwarding_enabled()) {
        upnp_http_SendErrorResponse(h, 713, "IPv6 forwarding is disabled");
        return;
    }

    struct sockaddr_storage client_addr;
    socklen_t client_len = sizeof(client_addr);

    if (getpeername(h->s, (struct sockaddr *)&client_addr, &client_len) < 0) {
        upnp_http_SendErrorResponse(h, 500, "Internal Error");
        return;
    }

    int timeout = check_outbound_pinhole_timeout(internalClient, internalPort, externalPort, remoteHost, protocol);
    if (timeout < 0) {
        upnp_http_SendErrorResponse(h, 720, "Action failed");
        return;
    }

    char soap_response[256];
    snprintf(soap_response, sizeof(soap_response),
             "<u:%sResponse xmlns:u=\"%s\">"
             "<NewRequestedPort>%s</NewRequestedPort>"
             "<NewPinholeTimeout>%d</NewPinholeTimeout>"
             "</u:%sResponse>",
             action, ns, externalPort, timeout, action);

    upnp_http_SendSoapResponse(h, soap_response);
}

