void handle_outbound_pinhole_timeout(struct upnphttp *h, const char *action, const char *ns) {
    if (!ipv6_forwarding_enabled()) {
        upnphttp_send_error(h, 400, "IPv6 forwarding is disabled.");
        return;
    }

    char *internal_client_ip = NULL;
    char *internal_port = NULL;
    char *remote_host = NULL;
    char *protocol = NULL;

    if (!upnphttp_get_query_var(h, "InternalClient", &internal_client_ip) ||
        !upnphttp_get_query_var(h, "InternalPort", &internal_port) ||
        !upnphttp_get_query_var(h, "RemoteHost", &remote_host) ||
        !upnphttp_get_query_var(h, "Protocol", &protocol)) {
        upnphttp_send_error(h, 400, "Missing required parameters.");
        free(internal_client_ip);
        free(internal_port);
        free(remote_host);
        free(protocol);
        return;
    }

    log_request_details(h, internal_client_ip, internal_port, remote_host, protocol);

    int timeout = check_outbound_pinhole_timeout(internal_client_ip, internal_port, remote_host, protocol);
    if (timeout < 0) {
        upnphttp_send_error(h, 500, "Failed to determine pinhole timeout.");
    } else {
        char response[256];
        snprintf(response, sizeof(response),
                 "<s:Envelope xmlns:s=\"http://schemas.xmlsoap.org/soap/envelope/\" s:encodingStyle=\"http://schemas.xmlsoap.org/soap/encoding/\">"
                     "<s:Body>"
                         "<u:%s xmlns:u=\"%s\">"
                             "<NewTimeout>%d</NewTimeout>"
                         "</u:%s>"
                     "</s:Body>"
                 "</s:Envelope>",
                 action, ns, timeout, action);

        upnphttp_send_response(h, 200, "text/xml", response);
    }

    free(internal_client_ip);
    free(internal_port);
    free(remote_host);
    free(protocol);
}

void upnp_http_get_outbound_pinhole_timeout(struct upnphttp *h, const char *action, const char *ns) {
    char *internal_client = NULL;
    char *internal_port = NULL;
    char *remote_host = NULL;
    char *protocol = NULL;
    int is_v6 = 0;
    int forward_v6 = 0;

    if (!forward_v6) {
        upnp_http_response(h, 400, "IPv6 forwarding is disabled.");
        return;
    }

    internal_client = upnp_http_getvar(h, "InternalClient");
    internal_port = upnp_http_getvar(h, "InternalPort");
    remote_host = upnp_http_getvar(h, "RemoteHost");
    protocol = upnp_http_getvar(h, "Protocol");

    if (!internal_client || !internal_port || !remote_host || !protocol) {
        upnp_http_response(h, 400, "Missing required parameters.");
        goto cleanup;
    }

    syslog(LOG_DEBUG, "Request for outbound pinhole timeout: %s, %s, %s, %s", internal_client, internal_port, remote_host, protocol);

    int timeout = 0;
    if (check_outbound_pinhole_timeout(internal_client, internal_port, remote_host, protocol, &timeout) != 0) {
        upnp_http_response(h, 500, "Failed to retrieve pinhole timeout.");
        goto cleanup;
    }

    char soap_response[1024];
    snprintf(soap_response, sizeof(soap_response),
             "<SOAP-ENV:Envelope xmlns:SOAP-ENV=\"http://schemas.xmlsoap.org/soap/envelope/\">"
             "  <SOAP-ENV:Body>"
             "    <u:%s xmlns:u=\"%s\">"
             "      <NewOutboundPinholeTimeout>%d</NewOutboundPinholeTimeout>"
             "    </u:%s>"
             "  </SOAP-ENV:Body>"
             "</SOAP-ENV:Envelope>",
             action, ns, timeout, action);

    upnp_http_send_response(h, 200, soap_response);

cleanup:
    if (internal_client) free(internal_client);
    if (internal_port) free(internal_port);
    if (remote_host) free(remote_host);
    if (protocol) free(protocol);
}
